// Pseudo-policy skeleton
function policyForTenant(ckne) {
  // map to allocation, eviction, prefetch
  const size = baseSize * (0.5 + ckne);
  const evict = Math.max(1, Math.floor(5 * (1 - ckne)));
  const prefetch = Math.round(10 * ckne);
  return {size, evict, prefetch};
}
